using Godot;
using GArray=Godot.Collections.Array;
public partial class KeyframeEditorOperations
{
    private static Control NewCanvas()=>GD.Load<GDScript>("res://Workspaces/SceneWorkspace/scripts/Timeline/actor_keyframe_canvas.gd").New().As<Control>();
    private static void Hint(Control owner,GodotObject target,string text){var hints=owner.Get("hints").AsGodotObject();if(hints==null)return;if(text.Length==0)hints.Call("end",target);else hints.Call("begin",target,text);}
    public void ready(Control owner)
    {
        owner.AddToGroup("actor_keyframe_editors");var panel=new PanelContainer();owner.Set("header_panel",panel);var style=new StyleBoxFlat{BgColor=new Color("18232f"),ContentMarginLeft=8,ContentMarginTop=4,ContentMarginBottom=4};style.SetCornerRadiusAll(6);panel.AddThemeStyleboxOverride("panel",style);owner.AddChild(panel);
        var heading=new Label{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,ClipText=true};owner.Set("heading",heading);var header=new HBoxContainer();panel.AddChild(header);header.AddChild(heading);var close=new Button{Text="← Actors",TooltipText="Return to actors; keep all keyframes"};header.AddChild(close);close.Pressed+=()=>owner.EmitSignal("close_requested");
        var ruler=NewCanvas();owner.Set("ruler",ruler);ruler.Set("model",owner.Get("model"));ruler.Set("timeline",owner.Get("timeline"));ruler.Set("ruler_only",true);ruler.ClipContents=true;owner.AddChild(ruler);
        var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill,HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled,ClipContents=true};owner.Set("track_scroll",scroll);owner.AddChild(scroll);var lanes=NewCanvas();owner.Set("lanes",lanes);lanes.Set("model",owner.Get("model"));lanes.Set("timeline",owner.Get("timeline"));lanes.Set("show_ruler",false);lanes.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;scroll.AddChild(lanes);
        var footer=new ScrollContainer{HorizontalScrollMode=ScrollContainer.ScrollMode.ShowNever,VerticalScrollMode=ScrollContainer.ScrollMode.Disabled,ClipContents=true,TooltipText="Scroll horizontally to reach more keyframe properties"};owner.Set("detail_scroll",footer);footer.GuiInput+=ev=>{if(ev is InputEventMouseButton mouse&&mouse.Pressed&&(mouse.ButtonIndex==MouseButton.WheelUp||mouse.ButtonIndex==MouseButton.WheelDown)){footer.ScrollHorizontal+=mouse.ButtonIndex==MouseButton.WheelUp?-80:80;footer.AcceptEvent();}};owner.AddChild(footer);var details=new HBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};details.AddThemeConstantOverride("separation",8);owner.Set("details",details);footer.AddChild(details);
        lanes.Connect("selection_changed",new Callable(owner,"_build_details"));lanes.Connect("move_requested",new Callable(owner,"_move_keys"));lanes.Connect("move_preview_requested",Callable.From<GArray,double>((ids,delta)=>{var actor=Actor(owner);var plan=key_move_plan(owner,ids,delta,Before(owner));if(actor!=null&&plan["valid"].AsBool())_timeline.restore_animation(Model(owner),actor,plan["tracks"].AsGodotArray());}));lanes.Connect("delete_requested",Callable.From<GArray>(ids=>{var actor=Actor(owner);if(actor!=null)_timeline.delete_keyframes(Model(owner),actor,ids);}));lanes.Connect("interaction_changed",Callable.From<string>(text=>{if(text.StartsWith("Esc cancels keyframe drag"))begin_edit(owner);else if(text.Length==0&&owner.Get("_editing").AsBool())cancel_edit(owner);Hint(owner,lanes,text);}));lanes.FocusEntered+=()=>Hint(owner,owner,"Click / Shift-click keys • Drag moves • Delete removes • Ctrl+A selects keys • ←/→ nudges");lanes.FocusExited+=()=>Hint(owner,owner,"");Model(owner).Connect("changed",new Callable(owner,"refresh"));owner.ClipContents=true;owner.Resized+=()=>layout_editor(owner);layout_editor(owner);refresh(owner);
    }
}
